Here is the commit message:
perf/x86/lbr: Remove cpuc->lbr_xsave allocation from atomic
 context

If the kernel is compiled with the CONFIG_LOCKDEP option, the conditional
might_sleep_if() deep in kmem_cache_alloc() will generate the following
trace, and potentially cause a deadlock when another LBR event is added:

  [] BUG: sleeping function called from invalid context at include/linux/sched/mm.h:196
  [] Call Trace:
  []  kmem_cache_alloc+0x36/0x250
  []  intel_pmu_lbr_add+0x152/0x170
  []  x86_pmu_add+0x83/0xd0

Make it symmetric with the release_lbr_buffers() call and mirror the
existing DS buffers.

Fixes: c085fb8774 ("perf/x86/intel/lbr: Support XSAVES for arch LBR read")
Signed-off-by: Like Xu <like.xu@linux.intel.com>
[peterz: simplified]
Signed-off-by: Peter Zijlstra (Intel) <peterz@infradead.org>
Tested-by: Kan Liang <kan.liang@linux.intel.com>
Link: https://lkml.kernel.org/r/20210430052247.3079672-2-like.xu@linux.intel.com

Here is the root cause:
The bug was caused by the allocation of `cpuc->lbr_xsave` being performed in an atomic context within the `intel_pmu_lbr_add` function. This allocation could lead to a situation where a sleeping function was called from an invalid context, potentially resulting in a deadlock when another LBR event was added, especially when the kernel was compiled with the `CONFIG_LOCKDEP` option.

Here is the patch:

 void intel_pmu_lbr_add(struct perf_event *event)
 {
-	struct kmem_cache *kmem_cache = event->pmu->task_ctx_cache;
 	struct cpu_hw_events *cpuc = this_cpu_ptr(&cpu_hw_events);

 	if (!x86_pmu.lbr_nr)
 		return;

 	if (event->hw.flags & PERF_X86_EVENT_LBR_SELECT)
 		cpuc->lbr_select = 1;

 	cpuc->br_sel = event->hw.branch_reg.reg;

 	if (branch_user_callstack(cpuc->br_sel) && event->ctx->task_ctx_data)
 		task_context_opt(event->ctx->task_ctx_data)->lbr_callstack_users++;

 	/*
 	 * Request pmu::sched_task() callback, which will fire inside the
 	 * regular perf event scheduling, so that call will:
 	 *
 	 *  - restore or wipe; when LBR-callstack,
 	 *  - wipe; otherwise,
 	 *
 	 * when this is from __perf_event_task_sched_in().
 	 *
 	 * However, if this is from perf_install_in_context(), no such callback
 	 * will follow and we'll need to reset the LBR here if this is the
 	 * first LBR event.
 	 *
 	 * The problem is, we cannot tell these cases apart... but we can
 	 * exclude the biggest chunk of cases by looking at
 	 * event->total_time_running. An event that has accrued runtime cannot
 	 * be 'new'. Conversely, a new event can get installed through the
 	 * context switch path for the first time.
 	 */
 	if (x86_pmu.intel_cap.pebs_baseline && event->attr.precise_ip > 0)
 		cpuc->lbr_pebs_users++;
 	perf_sched_cb_inc(event->ctx->pmu);
 	if (!cpuc->lbr_users++ && !event->total_time_running)
 		intel_pmu_lbr_reset();
-
-	if (static_cpu_has(X86_FEATURE_ARCH_LBR) &&
-	    kmem_cache && !cpuc->lbr_xsave &&
-	    (cpuc->lbr_users != cpuc->lbr_pebs_users))
-		cpuc->lbr_xsave = kmem_cache_alloc(kmem_cache, GFP_KERNEL);
 }


+void reserve_lbr_buffers(void)
+{
+	struct kmem_cache *kmem_cache;
+	struct cpu_hw_events *cpuc;
+	int cpu;
+
+	if (!static_cpu_has(X86_FEATURE_ARCH_LBR))
+		return;
+
+	for_each_possible_cpu(cpu) {
+		cpuc = per_cpu_ptr(&cpu_hw_events, cpu);
+		kmem_cache = x86_get_pmu(cpu)->task_ctx_cache;
+		if (!kmem_cache || cpuc->lbr_xsave)
+			continue;
+
+		cpuc->lbr_xsave = kmem_cache_alloc_node(kmem_cache, GFP_KERNEL,
+							cpu_to_node(cpu));
+	}
+}
+
 void intel_pmu_lbr_del(struct perf_event *event)
 {
 	struct cpu_hw_events *cpuc = this_cpu_ptr(&cpu_hw_events);

 	if (!x86_pmu.lbr_nr)
 		return;

 	if (branch_user_callstack(cpuc->br_sel) &&
 	    event->ctx->task_ctx_data)
 		task_context_opt(event->ctx->task_ctx_data)->lbr_callstack_users--;

 	if (event->hw.flags & PERF_X86_EVENT_LBR_SELECT)
 		cpuc->lbr_select = 0;

 	if (x86_pmu.intel_cap.pebs_baseline && event->attr.precise_ip > 0)
 		cpuc->lbr_pebs_users--;
 	cpuc->lbr_users--;
